package protocol

import "testing"

func TestMeshRoundTrip(t *testing.T){m:=MeshEnvelope{ContractVersion:"1.2",Operation:"execute",Payload:map[string]any{"x":1},CorrelationID:"corr-1",Source:"N07",Target:"N01"};b,err:=EncodeMesh(m);if err!=nil{t.Fatal(err)};d,err:=DecodeMesh(b);if err!=nil{t.Fatal(err)};if d.CorrelationID!=m.CorrelationID||d.Operation!=m.Operation{t.Fatal("mesh round-trip failed")}}
func TestMeshRejectsInvalidEnvelope(t *testing.T){cases:=[]MeshEnvelope{{},{ContractVersion:"1.2"},{ContractVersion:"1.2",Operation:"execute",CorrelationID:"c",Source:"N07"},{ContractVersion:"1.2",Operation:"execute",CorrelationID:"c",Source:"N07",Target:"N01"}};for i,m:=range cases{if i==len(cases)-1{if err:=m.Validate();err!=nil{t.Fatal(err)};continue};if _,err:=EncodeMesh(m);err==nil{t.Fatalf("case %d accepted",i)}}}
func TestMeshToN07PreservesGenericPayload(t *testing.T){meshMsg:=MeshEnvelope{ContractVersion:"soul-mesh/1",Operation:"tool.invoke",Payload:map[string]any{"tool":"memory.search","query":"hello","values":[]any{1.0,2.0}},CorrelationID:"trace-7",Source:"N01",Target:"N07",Metadata:map[string]string{"capability":"tools"}};msg,err:=MessageFromMesh(meshMsg);if err!=nil{t.Fatal(err)};if msg.TraceID!="trace-7"||msg.Source!="N01"||msg.Target!="N07"||msg.Operation!="tool.invoke"{t.Fatalf("message mapping=%+v",msg)};if len(msg.Payload)!=2||msg.Payload[0]!=1||msg.Payload[1]!=2{t.Fatalf("numeric payload lost: %v",msg.Payload)};back,err:=MeshFromMessage(msg);if err!=nil{t.Fatal(err)};if back.CorrelationID!=meshMsg.CorrelationID||back.Source!=meshMsg.Source||back.Target!=meshMsg.Target{t.Fatalf("round-trip envelope=%+v",back)};if back.Payload["tool"]!="memory.search"||back.Payload["query"]!="hello"{t.Fatalf("generic payload lost: %+v",back.Payload)}}
func TestMessageRejectsInvalidGenericPayload(t *testing.T){m:=NewMessage("N07","N01","tool","invoke",nil);m.PayloadJSON=[]byte("{invalid");if err:=m.Validate();err==nil{t.Fatal("invalid payload_json accepted")}}
